<section data-member-panel="incidencias" class="hidden"><div class="tfc-member-grid"><article><h2>Nueva incidencia</h2>@if($canManage)<form method="POST" action="{{ route('members.incidents.store', $member) }}" class="tfc-form">@csrf<label>Tipo<select name="type"><option value="attendance_failed">Asistencia</option><option value="membership">Bono</option><option value="payment">Pago</option><option value="reservation">Reserva</option><option value="conduct">Conducta</option><option value="documentation">Documentacion</option><option value="other">Otro</option></select></label><label>Prioridad<select name="severity"><option value="info">Informativa</option><option value="warning" selected>Aviso</option><option value="action_required">Requiere accion</option><option value="critical">Critica</option></select></label><label>Asunto<input name="title" maxlength="180" required></label><label>Cuando ocurrio<input type="datetime-local" name="occurred_at" value="{{ now()->format('Y-m-d\\TH:i') }}" required></label><label>Detalles<textarea name="details" maxlength="3000"></textarea></label><button class="tfc-button">Crear incidencia</button></form>@endif</article><article><h2>Abiertas</h2>@forelse($member->incidents->where('status','open') as $incident)<div class="tfc-member-note"><strong>{{ $incident->title }}</strong><p>{{ $incident->occurred_at->format('d/m/Y H:i') }} · {{ $incident->severity }}</p><p>{{ $incident->details }}</p>@if($canManage)<form method="POST" action="{{ route('members.incidents.resolve', [$member, $incident]) }}" class="tfc-form">@csrf<label>Resolucion<textarea name="resolution" required maxlength="3000"></textarea></label><button class="tfc-text-button">Resolver</button></form>@endif</div>@empty<p>No hay incidencias abiertas.</p>@endforelse</article></div><div class="tfc-table-wrap mt-6"><table class="tfc-table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Origen</th><th>Estado</th><th>Creada por</th></tr></thead><tbody>@forelse($member->incidents as $incident)<tr><td>{{ $incident->occurred_at->format('d/m/Y H:i') }}</td><td>{{ $incident->type }}</td><td>{{ $incident->source }}</td><td>{{ $incident->status }}</td><td>{{ $incident->createdBy?->name ?? 'Sistema' }}</td></tr>@empty<tr><td colspan="5" class="tfc-empty">Sin incidencias registradas.</td></tr>@endforelse</tbody></table></div></section>
